package com.mhtextractor.gui.acceptance;

import com.mhtextractor.i18n.I18n;
import com.mhtextractor.uicore.PreviewRow;
import javafx.geometry.Bounds;
import javafx.scene.control.Label;
import javafx.scene.control.ListCell;
import javafx.scene.control.ListView;
import javafx.scene.control.OverrunStyle;

/** Acceptance through public scene nodes, with no controller/member access. */
public final class SourceColumnAssertions {
    private SourceColumnAssertions() {}

    public static String verify(ListView<?> list, String expectedSource) {
        list.getScene().getRoot().applyCss();
        list.getScene().getRoot().layout();
        Label sourceHeader = (Label) list.getScene().lookup("#sourceColumnHeader");
        Label nameHeader = (Label) list.getScene().lookup("#nameColumnHeader");
        require(sourceHeader != null && sourceHeader.isVisible()
                && I18n.get("main.source").equals(sourceHeader.getText()), "Missing localized source header");
        int count = 0;
        boolean ellipsis = false;
        String evidence = "";
        for (var node : list.lookupAll(".list-cell")) {
            if (!(node instanceof ListCell<?> cell) || !(cell.getItem() instanceof PreviewRow row)
                    || !expectedSource.equals(row.sourceFolder) || cell.isEmpty() || !cell.isVisible()) continue;
            Label source = (Label) cell.lookup(".preview-source");
            Label name = (Label) cell.lookup(".preview-name");
            require(source != null && source.isVisible() && source.isManaged(), "Missing visible source cell");
            require(expectedSource.equals(source.getText()), "Source cell must preserve original source");
            require(source.getTooltip() != null && expectedSource.equals(source.getTooltip().getText()),
                    "Source tooltip must preserve full source");
            aligned(nameHeader, name);
            aligned(sourceHeader, source);
            require(source.getTextOverrun() == OverrunStyle.ELLIPSIS && !source.isWrapText(), "Source must elide");
            ellipsis |= source.isTextTruncated();
            count++;
            Bounds bounds = source.localToScene(source.getLayoutBounds());
            evidence = "x=" + bounds.getMinX() + " width=" + bounds.getWidth();
        }
        require(count > 0, "No visible source rows inspected");
        require(ellipsis, "Long source fixture must actually show an ellipsis");
        return "rows=" + count + " " + evidence + " ellipsis=true tooltip=" + expectedSource;
    }

    private static void aligned(Label header, Label cell) {
        Bounds a = header.localToScene(header.getLayoutBounds());
        Bounds b = cell.localToScene(cell.getLayoutBounds());
        require(Math.abs(a.getMinX() - b.getMinX()) <= 1 && Math.abs(a.getWidth() - b.getWidth()) <= 1,
